using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesYuanMingQing
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("dashun_li_zicheng",
                "李自成（1606年9月22日—1645年5月17日），原名鸿基，陕西米脂人，世居米脂李继迁寨，明末民变领袖之一，大顺皇帝。崇祯帝采信大臣裁撤驿卒的建议，造成失业驿卒武夫起义，李自成参与起义军。高迎祥被明朝处决后，李自成称闯王，成为明末民变领袖之一，率起义军于河南歼灭明军主力。1644年在西安称帝建立大顺，后进攻明都北京，与崇祯帝谈判破裂后，攻入北京城，崇祯自缢，是为甲申之变，至此明朝灭亡。");
            pEntries.Add("mengpai",
                "蒙派是本模组作者的历史化身，自南洋起兵并率部北返神州，最终创建以大汉为号的猴汉帝国。他在长期征战中整合军队、地方势力与行政体系，使新政权从远征集团转为稳定国家。这张彩蛋卡记录的是作者设定中的开国君主身份，其事迹属于模组世界观而非真实历史。");
            pEntries.Add("ming_chang_yuchun",
                "常遇春（1330年—1369年8月9日），字伯仁，号燕衡。祖籍南直隶怀远（今属安徽），和阳（和州，今安徽和县）人，明朝开国名将。元顺帝至正十五年（1355年），归附朱元璋，自请为前锋，力战克敌，尝自言能将十万众，横行天下，军中称常十万，官至中书平章军国重事，兼太子少保，封鄂国公。洪武二年，北伐中原，暴卒军中，年仅四十，用宋太宗丧韩王赵普故事，追赠翊运推诚宣德靖远功臣、开府仪同三司、上柱国、太保、中书右丞相，追封开平王，谥号忠武，配享太庙。");
            pEntries.Add("ming_chengzu",
                "明成祖朱棣（1360年5月2日—1424年8月12日），南直隶凤阳府（今安徽省凤阳县）人，生于应天府（今江苏省南京市），中国明初政治家与军事家，明太祖朱元璋第四子，明朝第三位皇帝，在位时间为1402年至1424年，年号永乐。其庙号原为太宗，嘉靖十七年（1538）改为成祖。洪武三年（1370年），朱棣被册封为燕王，洪武十三年（1380年）就藩北平。洪武二十三年（1390年），在明太祖发动的第七次北伐中，朱棣率军在漠北地区击败并招降北元乃儿不花部。");
            pEntries.Add("ming_daizong",
                "景泰帝朱祁钰（1428年9月21日—1457年3月14日），明朝皇帝（1449年9月22日－1457年2月24日在位），年号景泰。明宣宗朱瞻基皇次子，明英宗朱祁镇异母弟，母亲是贤妃吴氏。其于明英宗被俘后登基，往后在明英宗复辟后随即病死，遭废黜帝位并罢其皇帝号，将其贬回为郕王，上恶谥为“戾”，是为郕戾王。明宪宗朱见深复其皇帝位，改谥「恭仁康定景皇帝」，故后世称明景帝。");
            pEntries.Add("ming_fang_xiaoru",
                "方孝孺（1357年3月16日—1402年7月25日），字希直，又字希古，号逊志，南明弘光帝追谥文正，浙江台州宁海（今属宁波市）人。据《明初大儒方孝孺的书法艺术》（作者：林邦德）中记载，方孝孺生于1357年3月16日(阴历二月二十五日)。斋名逊志斋，蜀献王朱椿改之为正学，故世称正学先生。明朝建文年间重臣，文学家、思想家。");
            pEntries.Add("ming_gu_yanwu",
                "顾炎武（1613年7月15日—1682年2月15日），原名绛，字宁人。明亡后，改名炎武，亦曾化名蒋山佣。学者尊为亭林先生，直隶苏州府昆山县（今江苏昆山市）人，明末清初思想家、学者。与黄宗羲、王夫之并称“明末三大儒”、“明末三先生”或“明末三大思想家”。");
            pEntries.Add("ming_guangzong",
                "明光宗朱常洛（1582年8月28日—1620年9月26日），因年号泰昌亦称泰昌帝，明朝皇帝，谥号“崇天契道英睿恭纯宪文景武渊仁懿孝贞皇帝”。朱常洛是明神宗长子，万历十年八月十一日（1582年8月28日）生，母恭妃王氏原是祖母李太后身边的宫人。不久，明神宗郑贵妃生三子朱常洵，深得宠爱。长子朱常洛一直受到冷遇，群臣纷纷上书要求立储，是为国本之争，明神宗要不是贬斥群臣，就是虚与委蛇地敷衍应付。");
            pEntries.Add("ming_hai_rui",
                "海瑞（1514年1月23日—1587年11月13日），字汝贤，又字国开、应麟，号刚峰，广东琼州琼山县（今海南海口）人，祖籍广州番禺，明朝政治家。嘉靖己酉举人，初任教谕，升知县。嘉靖末年上疏切谏，痛砭时弊，言忤嘉靖帝，下狱论死。隆庆帝即位后得释，累升应天巡抚，人称“海青天”。");
            pEntries.Add("ming_hong_chengchou",
                "洪承畴（1593年10月16日—1665年4月3日），字彦演，号亨九，福建泉州府南安县英都（今英都镇良山村）人。明末清初政治人物和军事人物。崇祯时官至兵部尚书、蓟辽总督，松锦之战败战后降清，成为清朝首位汉人大学士。洪在明代时讨伐流寇、满人屡战皆捷，但在松锦之战兵败降清。");
            pEntries.Add("ming_huidi",
                "建文帝朱允炆（1377年12月5日—？）为明朝皇帝，年号“建文”，明太祖朱元璋之孙，早逝太子朱标之子。在位期间进行一系列宽政、削藩的改革，即建文改制，但亦因此触动藩王利益并导致燕王朱棣发动靖难之变，于燕军攻入京师应天府夺位成功后建文帝自此失踪。燕王即位为明成祖后不承认其合法性而未上谥号，故明朝人大多称之为建文君，但大臣梅殷私谥其为「神宗孝愍皇帝」。直到南明时，弘光帝方追谥其为“嗣天章道诚懿渊功观文扬武克仁笃孝让皇帝”，庙号“惠宗”；清高宗乾隆亦有追谥其为「恭闵惠皇帝」。");
            pEntries.Add("ming_lan_yu",
                "蓝玉（？—1393年），又名声远，苗族，南直隶定远（今属安徽）人，明初将领。与胡惟庸同乡，常遇春妻弟。洪武十二年秋封永昌侯，二十年拜征虏大将军。二十一年拜大将军、凉国公。");
            pEntries.Add("ming_li_dingguo",
                "李定国（1621年7月29日—1662年8月10日），字鸿远，又字宁宇、霖宇、一纯、大绶，陕西延安府（现属陕西省榆林市）人，南明晋王，抗清将领。李定国是明末民变势力之一大西将领，张献忠义子，封为安西将军。大西大顺三年末（1647年初）张献忠战死后，与孙可望等率大西军余部南逃至云南称安西王。后与一众大西将领一同归顺南明，成为永历朝廷重要的抗清将领。");
            pEntries.Add("ming_li_shanchang",
                "李善长（1314年—1390年7月6日），字百室。本名李士元，后避讳明太祖朱元璋而改名。明朝开国功臣，曾任中书省丞相。李善长早年投靠朱元璋，跟随征战。");
            pEntries.Add("ming_li_shizhen",
                "李时珍（1518年7月3日—1593年），字东璧，晚号濒湖山人，湖广蕲州（今湖北省黄冈市蕲春县蕲州镇）人，籍贯福建上杭，明朝及中国历史上最着名的医学家、药学家和博物学家之一，其所着的《本草纲目》是本草学集大成的着作，对后世医学和博物学研究影响深远。李时珍与扁鹊、华佗和张仲景并称中国古代四大名医。祖父李晓山是铃医（摇串铃行医的走方郎中）；父亲李言闻，字子郁，号月池，也是当地名医。由于家庭熏陶，李时珍从小就喜爱医学。");
            pEntries.Add("ming_liu_bowen",
                "刘伯温（1311年7月1日—1375年5月16日），名基，字伯温，以字行，浙江省青田县（今文成县）人，祖籍陕西保安（志丹），南宋抗金将领刘光世的后人。元末明初军事家、政治家，文学家及诗人，通经史、晓天文、精兵法。他以辅佐明太祖朱元璋完成帝业、开创明朝并保持国家安定，因而驰名天下，被后人比作为诸葛武侯。朱元璋多次称刘基为：「吾之子房也。");
            pEntries.Add("ming_muzong",
                "齐东安和王朱载垕（hòu）（？—？），明朝衡藩第二代齐东王，齐东温惠王朱厚炳庶长子。朱载垕为衡王朱佑楎孙，祖母为诸氏。朱载垕早年被封为镇国将军。");
            pEntries.Add("ming_qi_jiguang",
                "戚继光（1528年11月12日—1588年1月17日），字元敬，号南塘、孟诸，山东登州府人，明朝将领。戚继光出身军户，奉命戍守浙江和福建十多年，招募士兵组成戚家军，练兵严格，军法严厉，创立新战术，注重武艺训练，多次击败倭寇，肃清闽浙的倭乱，战蹟彪炳，从参将多番转迁，升任福建总兵。后来戚继光受命镇守北方边境防范蒙古，得到首辅张居正和兵部尚书谭纶的信任，担任蓟州总兵十四年，重修长城，建造塔楼加强防务，官拜左都督，加封少保兼太子太保，地位显赫。");
            pEntries.Add("ming_renzong",
                "明仁宗朱高炽（1378年8月16日—1425年5月29日），年号洪熙，明成祖嫡长子，其母为仁孝文皇后，中山王徐达外孙，明朝皇帝。洪武二十八年（1395年）闰九月廿一日，被封为燕王世子，并娶兵马指挥张麒女为世子妃。靖难之役中，仁宗负责镇守北平，成功抵御李景隆率领的中央军围攻。永乐二年（1404年），立为皇太子，并在明成祖屡次北伐中，担任监国职位，实际负责国家政事。");
            pEntries.Add("ming_shenzong",
                "明神宗朱翊钧（1563年9月4日—1620年8月18日），或称万历帝，号禹斋，为明朝皇帝，年号万历，明穆宗朱载坖三子，生母李贵妃。隆庆六年（1572年）穆宗驾崩，九岁的朱翊钧登基，是为明神宗。在位48年，是明代在位时间最长的皇帝，谥号为「范天合道哲肃敦简光文章武安仁止孝显皇帝」。明神宗在位前十五年，在首辅兼帝师张居正的领导下明朝一度呈现中兴景象，史称万历中兴，而在位中期亦主持万历三大征，保护藩属，巩固疆土。");
            pEntries.Add("ming_shi_kefa",
                "史可法（1602年12月16日—1645年5月20日），字宪之，又字道邻，南明隆武朝廷谥忠烈，监国鲁王朝廷谥忠靖，永历朝廷改谥文忠。河南开封府祥符县人（今河南开封市），锦衣卫籍。明末政治人物，东林党人，与姜曰广、高弘图并称“南中三贤相”。弘光时官至南京兵部尚书、东阁大学士，追赠太师。");
            pEntries.Add("ming_shizong",
                "明世宗朱厚熜（1507年9月16日—1567年1月23日），或称嘉靖帝，号尧斋，一号雷轩，又号天池钓叟，明朝皇帝，庙号世宗，年号嘉靖。正德十六年（1521年），明武宗驾崩无嗣，内阁首辅杨廷和立宗室旁支的朱厚熜入继大统，即明世宗。明世宗是明宪宗之孙，明孝宗之侄，明武宗堂弟，兴献王朱佑杬次子，谥号「钦天履道英毅圣神宣文广武洪仁大孝肃皇帝」。世宗前期进行改革，锐意图治，颇有作为，他说道：“今天下诸司官员，比旧过多。");
            pEntries.Add("ming_sizong",
                "崇祯帝朱由检（1611年2月6日—1644年4月25日），字德约，明光宗第五子，明熹宗异母弟。是中国明朝末代皇帝，于1627年至1644年在位，年号“崇祯”。朱由检在其兄弟中排行第三。五岁时，其母刘氏被时为太子的光宗下令杖杀，年幼的朱由检随即交由庶母西李抚养，数年后改由另一庶母东李抚养至成人，后于天启二年（1622年）被其兄长明熹宗册封为信王。");
            pEntries.Add("ming_song_lian",
                "宋濂（1310年11月4日—1381年6月24日），字景濂，号潜溪，又号玄真子，谥文宪（私谥渊颖），浙江金华浦江县人。明初政治家、文学家、史学家。方孝孺之师，曾任翰林，修《元史》。后因胡惟庸案牵连，被明太祖谪死蜀地。");
            pEntries.Add("ming_sun_chuanzing",
                "孙传庭（1593年—1643年11月13日），字百雅，号白谷，山西代州振武卫（今代县）人，祖籍河南光山，明末政治人物，军事将领。万历己未进士，与流寇交战多年，曾生擒高迎祥。崇祯末以兵部尚书为督师，防守潼关，在朝廷催促下强行出战李自成，大败身死。");
            pEntries.Add("ming_taizu",
                "明太祖朱元璋（1328年10月21日—1398年6月24日），字国瑞，濠州钟离县（今安徽省凤阳县）人，中国元末明初政治家、军事家、诗人与农民起义领袖，是中国历史人物、明朝的开国皇帝，在位三十一年，年号“洪武”，庙号「太祖」，谥号「开天行道肇纪立极大圣至神仁文义武俊德成功高皇帝」，统称「太祖高皇帝」。朱元璋原名朱重八，生于贫农家庭，幼时曾为地主放牛，后因灾变家人俱亡，曾一度剃发出家，四处流浪化缘为生。1352年，参加郭子兴领导的农民起义红巾军反抗元朝政权，并受郭子兴取名元璋。");
            pEntries.Add("ming_tang_xianzu",
                "汤显祖（1550年9月24日—1616年7月29日），字义仍，号海若、若士，晚号茧翁，别署清远道人，室名玉茗堂。明代政治家、文学家、戏曲家、教育家。万历十一年（1583年）癸未科进士，历任南京太常寺博士、詹事府主簿、南京刑部主事、南京礼部祠祭清吏司主事，谪广东徐闻县典史、浙江遂昌县知县。其戏曲非常知名，乃与莎士比亚同期及影响力相若的伟大剧作家，也有“东方的莎士比亚”之称。");
            pEntries.Add("ming_wang_shizhen",
                "王世贞是明代后期文学家和史学家，与李攀龙共同主持后七子文坛，倡导复古诗文。他的父亲王忬在严嵩当政时被处死，王世贞长期搜集材料揭露严氏政治，并在仕途中屡受牵制。其《弇州山人四部稿》《弇山堂别集》等著作保存大量晚明文学、制度和史事资料。");
            pEntries.Add("ming_wang_yangming",
                "王守仁（1472年10月31日—1529年1月9日），幼名云，字伯安，号阳明子，浙江绍兴府余姚县（今浙江省余姚市）人，明代中期乃至中国历史上重要和影响深远的思想家、哲学家、书法家、文学家、政治家、军事家、教育家、儒生、心学家，也是汉字文化圈中最重要的儒家学者之一，在儒家之中占有极其重要的地位。官至南京兵部尚书、都察院左都御史，因平定宸濠之乱等军功而封爵新建伯，隆庆时追赠侯爵。他是陆王心学之集大成者，不但精通儒、释、道三教，而且能统军征战。");
            pEntries.Add("ming_wu_sangui",
                "吴三桂（1612年6月8日—1678年10月2日），字长伯，辽西（今辽宁绥中县）人，明末清初政治家、军事家，为明清改朝换代的关键人物之一。其祖籍南直隶高邮州（今江苏省高邮市），为锦州总兵吴襄之子，祖大寿外甥。明崇祯年间以父荫袭为辽东总兵，镇守山海关并受封「平西伯」。1644年降清并引清军入关，被满清封为「平西王」，更于1662年绞杀南明永历帝。");
            pEntries.Add("ming_wuzong",
                "明武宗朱厚照（1491年10月26日—1521年4月20日），明孝宗朱佑樘与张皇后长子，号锦堂老人，于西元1505年至1521年在位，年号「正德」，故又称为正德帝，谥号“承天达道英肃睿哲昭德显功弘文思孝毅皇帝”。明武宗是中国历史上极具争议性又极具个性的一位皇帝。他任情恣性，为人嬉乐胡闹，行为怪异，又荒淫无度。宠信宦官、引起安化王、宁王之乱，建立豹房，强徵处女入宫。");
            pEntries.Add("ming_xianzong",
                "明宪宗朱见濡（1447年12月9日—1487年9月9日），或称成化帝，原名朱见深，后改名朱见濡，为明英宗皇长子，明朝皇帝。明宪宗在位二十三年，期间恢复其叔朱祁钰的帝号，又为于谦等忠臣平反，初年励精图治，体恤民情，任用李贤、商辂、彭时等贤臣，颇为时人所传诵；在军事方面，整饬戎政，对内平定荆襄群盗和西南傜蛮，对外抵御鞑靼女真、收复河套、经略哈密，立下不少功绩。是明朝自仁宣之治后评价较高的皇帝。宪宗宠嬖万氏、中晚年信用汪直、梁芳、万安等宦官和宰辅，扩置“皇庄”大肆侵占土地。");
            pEntries.Add("ming_xiaozong",
                "明孝宗朱佑樘（1470年7月30日—1505年6月8日），或称弘治帝，是明宪宗皇三子。明朝皇帝，1487年－1505年在位，共十八年，年号弘治。孝宗“恭俭有制，勤政爱民”，又能信用贤臣、广开言路，在位期间“朝序清宁，民物康阜”，明朝出现中兴局面，史称“弘治中兴”。就其个人修养及文治武功而言，是明朝自仁宣二帝后，获后世普遍评价最高的皇帝。");
            pEntries.Add("ming_xie_jin",
                "解缙（1369年—1415年2月22日），字大绅，号春雨，谥文毅，江西吉水州（今江西吉安吉水县监湖）人，明朝第一位内阁首辅，主编《明太祖实录》与《永乐大典》。解缙天生聪颖，据传襁褓中就开始习字，四岁时，只要听过一遍，就能背诵诗词，七岁能诗，十岁时，每天背诵一篇千言文章，十二岁时，四书五经倒背如流，还能讲解，有神童之誉。洪武二十年（1387年）中式丁卯科江西乡试第一名举人。次年，洪武二十一年（1388年），再捷戊辰科三甲第十名进士，入翰林院，授中书庶吉士，时年十九岁。");
            pEntries.Add("ming_xizong",
                "明熹宗朱由校（1605年12月23日—1627年9月30日），或称天启帝，光宗长子，明朝皇帝。在位时间为1620年—1627年，年号天启。光宗即位仅一月便驾崩，使朱由校匆匆登基为帝，朱由校当时年仅十四岁，未曾被立为太子，故未接受过正规的储君教育。天启帝在位时面临后金严峻的挑战和日益加剧的社会危机，早期任用了东林党人主政，但中后期发生了东林党争和魏忠贤乱政等事件，后世中外史家普遍对天启帝给予相当恶劣的评价。");
            pEntries.Add("ming_xu_da",
                "徐达（1332年—1385年），字天德，濠州锺离永丰乡（今安徽凤阳东北）人，明朝开国功臣。元朝末年，徐达参加了朱元璋军队，追随其击败陈友谅、张士诚，朱元璋任为左相国。至正二十七年（1367年），任征虏大将军，与副将军常遇春一起北伐中原，攻占元大都。此后又连年出兵打击北元势力。");
            pEntries.Add("ming_xu_jie",
                "徐阶（1503年10月9日—1583年），字子升，号少湖，一号存斋，直隶松江府华亭县（今上海市松江区）人，明代政治家、文学家及思想家，官至内阁首辅、吏部尚书、建极殿大学士。徐阶自幼善于读书，少年时期结识阳明学江右学派门人聂豹。他弱冠之年乡试中举，殿试联登探花，受到杨廷和极高的赞赏。嘉靖早年张璁执掌朝廷时，徐阶直言反对张璁的提议，被贬出京城。");
            pEntries.Add("ming_xuanzong",
                "明宣宗朱瞻基（1399年3月16日—1435年1月31日），或称宣德帝，明仁宗嫡长子，永乐九年（1411年）立为皇太孙；永乐二十二年（1424年）十月立为皇太子。洪熙元年（1425年）即位，次年改元宣德，在位九年，享年36岁。宣德元年（1426年）平定朱高煦之乱。和其父明仁宗一样，比较能倾听臣下的意见，并称「仁宣之治」。");
            pEntries.Add("ming_yang_shiqi",
                "杨士奇由布衣进入建文朝编纂机构，永乐以后长期服务内阁，与杨荣、杨溥并称“三杨”。仁宗、宣宗时期他主张休养生息、减轻赋役并反对轻率用兵，是仁宣之治的重要决策者。晚年其子杨稷违法害民牵连家声，但杨士奇数十年的内阁经历仍塑造了明初文官中枢。");
            pEntries.Add("ming_yao_guangxiao",
                "姚广孝（1335年—1418年），幼名天禧，赐名广孝，法名道衍，字斯道，又字独闇，庵号独庵（独庵），号独庵老人、逃虚子，通称姚道衍。江浙等处行中书省平江路（明为南直隶苏州府）长洲县（今江苏省苏州市）人，祖籍开封府汴梁（一说为福州府长乐县文岭镇姚坑村）。中国元末明初政治人物、 临济宗僧人、诗人，明成祖靖难之役的叛臣之一，亦为协助朱棣篡位夺权的第一功臣。");
            pEntries.Add("ming_yingzong",
                "明英宗朱祁镇（1427年11月29日—1464年2月23日），明宣宗朱瞻基长子，母亲孝恭章皇后，明景帝朱祁钰异母兄，是明朝皇帝；最初使用「正统」（1436年－1450年）年号，复辟后使用「天顺」（1457年－1464年）年号，在位22年。谥号「法天立道仁明诚敬昭文宪武至德广孝睿皇帝」。他是明朝唯一使用多于一个年号的皇帝（明太祖朱元璋的“吴元年”是于明朝建立前所使用的，所以不算作其在明朝期间使用的年号）。其在第一段统治期间，在土木堡之变被俘，为宋代后唯一因军事失利而被俘虏的皇朝君主。");
            pEntries.Add("ming_yu_dayou",
                "俞大猷（1503年—1579年），字志辅，号虚江，福建泉州府晋江县濠市河格头村（今福建省泉州市洛江区河市镇河市村）人，祖籍南直隶凤阳府霍邱县（今安徽）。是明代嘉靖年间与戚继光齐名的抗倭名将，亦是武术家、军事家、诗人。曾任浙江总兵、福建总兵，追赠左都督，谥武襄。");
            pEntries.Add("ming_yu_qian",
                "于谦（1398年—1457年2月16日），字廷益，号节庵，谥忠肃，明朝大臣，浙江杭州府钱塘县（今浙江省杭州市）人。于谦，永乐十九年辛丑科同进士出身，因参与平定朱高煦之乱有功，得到明宣宗器重，巡抚山西、河南等地。明英宗时期，因得罪王振下狱，释放后起为兵部侍郎。土木堡之变后，于谦继任兵部尚书，指挥明军取得北京保卫战的胜利。");
            pEntries.Add("ming_yuan_chonghuan",
                "袁崇焕（1584年6月6日—1630年9月22日），字元素，号自如（一说字自如），广西梧州府藤县籍，广东东莞县（今属广东省东莞市）水南村（临近东江）人，据考为疍家人，明朝末年政治人物，万历四十七年（1619年）中进士，累官兵部尚书兼蓟辽督师，守卫山海关及辽东，构筑「关宁锦防线」，多次和后金部队交战，曾指挥宁远之战、宁锦之战。对崇祯帝承诺“五年平辽”，得言听计从，支给钱粮。后因诛杀毛文龙、在己巳之变护卫不力以及擅自与后金议和等事由被罗织入罪并被判以凌迟之刑。");
            pEntries.Add("ming_zhang_juzheng",
                "张居正（1525年5月26日—1582年7月9日），字叔大，号太岳，人称张江陵，湖广荆州府江陵县（今湖北荆州江陵县）人，荆州卫军籍。祖籍直隶凤阳，万历初年的政治家、改革家，权臣，期间官至太师、吏部尚书兼中极殿大学士，为内阁首辅长达十年，其间成为实际最高领导人，掌握最高权力。他知人善任，重用名将李成梁、戚继光等，镇守北部边防，为改革营造稳定的外部环境；任用潘季驯治理黄河，卓有成效。任内推行一条鞭法与考成法，改革赋税与官吏考核制度，影响深远。");
            pEntries.Add("ming_zheng_he",
                "郑和（1371年9月23日—1433年），原姓马，小名三宝，又作三保，云南昆阳县（今云南省昆明市晋宁区）人，明成祖赐姓郑，故称郑和。中国明朝军事家、航海家、外交家及宦官。郑和在参与靖难之役后，奉明成祖之命率领帝国舰队开始他的七次远航，历时二十八年，访问三十多个西太平洋和印度洋沿岸国家和地区，史称「郑和下西洋」，总航程达七万多海里。郑和下西洋是中国历史上第一次由中原王朝官方大规模组织的大航海，足足早了西方半个多世纪，其航程之远及船队规模之大，为当时罕见。");
            pEntries.Add("nanming_hongguang",
                "弘光帝朱由崧（1607年9月5日—1646年7月1日），为南明首位皇帝，即位前原为明朝福王。其为明神宗朱翊钧之孙、福忠王朱常洵之子、明熹宗朱由校、崇祯帝朱由检之堂兄弟。崇祯帝殉国后，朱由崧在南京即位，改元弘光，当年清军随即南攻，朱由崧被俘，押往北京，翌年被处决，在位仅有一年。南明永历帝为其上庙号「安宗」，谥号奉天遵道宽和静穆修文布武温恭仁孝简皇帝。");
            pEntries.Add("nanming_longwu",
                "隆武帝朱聿键（1602年5月25日—1646年10月6日），小字长寿，南明第二代皇帝。原为「唐王」，为明太祖朱元璋二十三子唐王朱桱的八世孙（与明神宗同辈份），祖父唐端王朱硕熿，父为唐王之子朱器墭，母宣皇后毛氏。1644年，崇祯帝在北京自缢。1645年，弘光帝被俘，郑芝龙、黄道周等人扶唐王朱聿键于福州登基称帝，改元为隆武并于同年开铸「隆武通宝」，而弘光帝在翌年被清廷所杀。");
            pEntries.Add("nanming_yongli",
                "永历帝朱由榔（1623年11月1日—1662年6月1日），是南明第四位也是最后一位皇帝，延平王郑经追尊其为“昭宗匡皇帝”。隆武元年（清顺治三年，1646年)，南明隆武帝被俘死，桂王朱由榔自称监国。不久，隆武帝之弟唐王朱聿鐭在广东广州继位，以次年为绍武元年，是为「绍武帝」。数日后，桂王朱由榔在广东肇庆亦登基称帝，年号永历，是为「永历帝」。");
            pEntries.Add("qing_dezong",
                "光绪帝（1871年8月14日—1908年11月14日），名载湉（tián），爱新觉罗氏，中国清朝皇帝，于公元1875年至1908年在位，年号“光绪”，庙号德宗，谥号景皇帝。通称光绪皇帝、景皇帝，是中国最后一位获正式谥号及庙号的皇帝。载湉是醇亲王奕譞和嫡福晋叶赫那拉氏次子，道光帝之孙，咸丰帝侄儿，同治帝堂弟兼表弟，并为慈禧太后外甥（后为养子），原非皇位嫡系。1875年初，无子的同治帝去世，慈安与慈禧两宫皇太后决定由载湉继位，过继为咸丰帝之子，登基为帝。");
            pEntries.Add("qing_dorgon",
                "多尔衮，满洲爱新觉罗氏，清朝初年宗室、皇父摄政王、权臣、八旗领袖、清朝入关后奠基者之一，曾一度追尊为皇帝，庙号“成宗”，谥号「懋德修道广业定功安民立政诚敬义皇帝」。清太祖努尔哈赤第十四子，清太宗皇太极之弟，清世祖福临的叔父，母为清太祖努尔哈赤大妃阿巴亥（乌拉纳喇氏），同母兄英亲王阿济格，同母弟豫亲王多铎。1626年封贝勒，后因战功封“和硕睿亲王”。顺治朝初年实际上最高领导人，多尔衮清军入关，对巩固清朝在中原统始、统一中原、满人汉化起了关键作用，奠定满清往后200多年在中原的统治基础。");
            pEntries.Add("qing_fan_wencheng",
                "范文程（1597年—1666年），字宪斗，汉军镶黄旗人，清朝初年政治家、谋臣、军事家、重臣、汉臣首领、儒学家。其先世于明初自江西贬往沈阳，“居抚顺所”。努尔哈赤攻占抚顺，范文程主动投靠。历事满洲四代君主，清朝开国时的规制大多出自其手，更被视为文臣之首。");
            pEntries.Add("qing_gaozong",
                "乾隆帝（1711年9月25日—1799年2月7日），名弘历，爱新觉罗氏，法号长春居士，中国清朝皇帝，年号「乾隆」，庙号高宗，谥号简称纯皇帝。乾隆帝是雍正帝第四子，生于康熙五十年（1711年辛卯年），登基于雍正十三年（1735年乙卯年）。因继位之时有在位时间不超越其祖父康熙帝（61年）之誓言，故于乾隆六十年（1795年）禅位于其十五子颙琰，至此总共在位60年，是中国历史上在位时间第二长的皇帝。禅位后，乾隆成为太上皇，依然手握大权，仍是大清帝国实际上的最高统治者，直到嘉庆四年（1799年）驾崩，享寿八十七岁（虚岁八十九岁），是中国历史上最长寿的皇帝以及实际掌权时间最长的皇帝，葬于清东陵中的裕陵。");
            pEntries.Add("qing_gong_zizhen",
                "龚自珍（1792年8月22日—1841年9月26日），字璱人，号定盦。曾字尔玉 ，曾更名易简，字伯定，再更名为巩祚，浙江杭州府仁和县人，清朝中后期思想家、文学家。乾隆五十七年七月初五日（1792年8月22日）生于杭州城东马坡巷小采园（今有纪念馆于此），是龚家的长房长孙。六岁随父母租居北京绳匠胡同、潘家河、门楼胡同、手帕胡同和城外上斜街等处。");
            pEntries.Add("qing_ji_yun",
                "纪昀（1724年8月3日—1805年3月14日），字晓岚，以字行，号石云、观弈道人、孤石老人、河间才子，直隶省河间府献县（今河北省沧州市献县）人，清代乾隆年间学者，政治人物。官至礼部尚书、协办大学士，曾任《四库全书》总纂修官。纪昀文采超群，与同时代江南的袁枚齐名，时称「北纪南袁」。");
            pEntries.Add("qing_li_hongzhang",
                "李鸿章（1823年2月15日—1901年11月7日），训名章铜，字子黻、渐甫，号少荃、仪叟、省心，人称李中堂、李傅相。安徽庐州合肥人（今属合肥市），晚清重臣，近代中国重要的政治家、军事家、外交家、实业家、改革家。李鸿章为曾国藩门生，道光丁未进士，累官至太子太傅、文华殿大学士、北洋通商大臣、直隶总督，爵位一等肃毅伯。他创立地方武装淮军，训练西式海军北洋水师，并参与讨伐太平军、平定捻军、洋务运动、中法战争、甲午战争及义和团运动。");
            pEntries.Add("qing_liang_qichao",
                "梁启超（1873年2月23日—1929年1月19日），署名作梁超，字卓如、宏猷、任甫，别号任公、饮冰室主人，广东省广州府新会县潮居都茶坑乡人，人称梁新会。被称为“百科全书式的人物”。他在青年时期与康有为合作进行戊戌变法，失败后流亡日本，在海外推动清朝君主立宪。清末时期，他首次提出中华民族的概念。");
            pEntries.Add("qing_lin_zexu",
                "林则徐（1785年8月30日—1850年11月22日），字元抚，又字少穆、石麟，晚号竢村老人、竢村退叟、七十二峰退叟、瓶泉居士、栎社散人等，男，福建省福州府侯官县左营司巷（今福州市鼓楼区）人，文山林氏，清朝后期政治家、思想家、文学家、改革先驱、诗人、学者、翻译家。1811年林则徐（26岁）中进士，后曾官至一品，曾经担任湖广总督、陕甘总督和云贵总督，两次受命钦差大臣。1839年，林则徐至广东禁菸，使威廉·渣甸、兰斯禄·颠地等鸦片商人交出鸦片，将收到的鸦片于虎门销毁。");
            pEntries.Add("qing_muzong",
                "同治帝（1856年4月27日—1875年1月12日），名载淳，爱新觉罗氏，中国清朝皇帝，于公元1861年至1875年在位，年号“同治”，庙号穆宗，谥号简称毅皇帝。载淳是咸丰帝与其懿贵妃（即慈禧太后）所生长子，亦是咸丰帝唯一存活成人的儿子。1860年，英法联军攻占北京，咸丰帝北逃热河行宫，并于翌年驾崩。年仅六岁的载淳即皇帝位，原设年号为「祺祥」，辛酉政变后改为「同治」。");
            pEntries.Add("qing_renzong",
                "嘉庆帝（1760年11月13日—1820年9月2日），名颙（yóng）琰（yǎn），爱新觉罗氏，中国清朝皇帝，于1796年至1820年在位，年号“嘉庆”，庙号仁宗，谥号简称睿皇帝。嘉庆帝原名永琰，是乾隆帝第十五子，于乾隆六十年（1795年）被立为皇太子，为避免避讳之麻烦而更名颙琰。1795年，接受父亲乾隆帝禅位而成为皇帝，但乾隆帝虽然禅让皇位，却仍然以太上皇的身份「训政」，在退位后持续执掌国政大权将近三年之久，直到1799年乾隆帝驾崩后才得以亲政。");
            pEntries.Add("qing_shen_baozhen",
                "沈葆桢（1820年4月9日—1879年12月18日），榜名振宗，字翰宇、幼丹，福建省福州府侯官县（今福建省福州市鼓楼区）人，晚清大臣。他是“同治中兴”时洋务运动的重要人物之一，先后曾任江西巡抚、总理船政大臣、台湾海防钦差大臣、两江总督兼南洋通商大臣，对台湾历史发展也有重大影响。其妻林普晴是清朝名臣林则徐的三女。");
            pEntries.Add("qing_shengzu",
                "康熙帝（1654年5月4日—1722年12月20日），名玄烨（yè），爱新觉罗氏，中国清朝皇帝，于公元1661年至1722年在位，年号康熙，庙号圣祖，通称圣祖仁皇帝。玄烨为顺治帝第三子，生母为孝康章皇后佟佳氏。1661年，顺治帝驾崩，临终立玄烨为储君。康熙帝即位时不到8岁，辅政大臣鳌拜独揽大权。");
            pEntries.Add("qing_shizong",
                "雍正帝（1678年12月13日—1735年10月8日），名胤（yìn）禛（zhēn），爱新觉罗氏，法号破尘居士、圆明居士，中国清朝皇帝，于公元1722年至1735年在位，年号「雍正」。庙号世宗，谥号敬天昌运建中表正文武英明宽仁信毅睿圣大孝至诚宪皇帝，通称世宗宪皇帝。胤禛是康熙帝皇四子（实为十一子），生母孝恭仁皇后乌雅氏。康熙六十一年（1722年）冬，康熙帝逝世，胤禛遵遗诏即位，是清朝首位依照秘密立储遗诏即位的皇帝。");
            pEntries.Add("qing_shizu",
                "顺治帝（1638年3月15日—1661年2月5日），本名福临，原名方喀拉，法号明觉禅师、痴道人，法名行痴，为第二位清朝皇帝，也是首位君临中国本土的清朝皇帝。1643年其父皇太极崩逝后，议政王大臣会议推举年方5岁的方喀拉嗣位，改名福临，年号“顺治”，并命两位亲王辅政，即努尔哈赤第十四子睿亲王多尔衮及努尔哈赤之侄郑亲王济尔哈朗，二人皆属爱新觉罗宗室。1644年11月，顺治帝于北京登极，践祚为中国皇帝。自1643年至1650年，朝政大权多掌于摄政王多尔衮之手。");
            pEntries.Add("qing_taizong",
                "皇太极，爱新觉罗氏，是后金汗（1626年10月20日－1636年5月14日在位）及清朝开国皇帝（1636年5月15日－1643年9月21日在位），即清太宗。即位初年号“天聪”，1636年改后金为大清时，年号改为“崇德”。皇太极是后金建立者努尔哈赤第八子。1626年，努尔哈赤逝世，皇太极继承汗位，年号天聪，当时后金的实际统治区域为现中国东北大部及俄罗斯远东部分地区。");
            pEntries.Add("qing_taizu",
                "努尔哈赤，爱新觉罗氏，出身建州左卫都指挥使世家旁系，后金的第一位汗，后世被尊为清太祖，东北民间俗称老罕王。他是明末女真首领，后金创始人、清朝奠基人之一。其祖父觉昌安被明朝授予都指挥使，父亲塔克世为觉昌安第四子，母亲是宣皇后喜塔喇氏，努尔哈赤为嫡长子。努尔哈赤少年时曾以采参为生，被辽东总兵李成梁收养，常到抚顺关马市贸易。");
            pEntries.Add("qing_wenzong",
                "咸丰帝（1831年7月17日—1861年8月22日），名奕（zhǔ），爱新觉罗氏，中国清朝皇帝，于公元1850年至1861年在位，年号“咸丰”，庙号文宗，谥号简称显皇帝，号且乐道人。咸丰帝是道光帝第四子，生母为孝全成皇后钮祜禄氏，诞于北京圆明园澄静斋。1850年，其父道光帝驾崩，时年20岁的咸丰帝依据遗诏即位。咸丰帝是清朝及中国历史上最后一位掌握实际统治权的皇帝，也是最后一位经由储位密建的皇帝，其在位期间，清朝国势衰微，各种社会矛盾轮番激化爆发，内有太平天国运动、捻军、黄河决口等民变灾殃，外有第二次鸦片战争、俄国趁火打劫等祸患，时局动荡艰困，几无宁日，令原本有心发奋勤政的咸丰帝心力交瘁、万念俱灰。");
            pEntries.Add("qing_xuantong",
                "溥（pǔ）仪，爱新觉罗氏，是清朝及中国历史上最后一位皇帝，也是满洲国的唯一一位君主。溥仪为道光帝的曾孙，光绪帝的侄子。其生父为醇亲王载沣，生母幼兰是晚清重臣荣禄之女。1908年11月，光绪帝驾崩，慈禧太后在临终之际立年近3岁的溥仪为帝，兼祧同治帝和光绪帝；同年12月2日，溥仪正式即位，于翌年改元“宣统”。");
            pEntries.Add("qing_xuanzong",
                "道光帝（1782年9月16日—1850年2月25日），名旻（mín）宁（满语：，穆麟德转写：Min ning，原名绵宁，满洲爱新觉罗氏，中国清朝皇帝，于公元1820年至1850年在位，年号“道光”，庙号宣宗，谥号简称成皇帝，通称清宣宗、宣宗成皇帝或道光（皇）帝，其墓葬是清西陵中的慕陵。道光帝为嘉庆帝次子，生母为孝淑睿皇后喜塔腊氏。是清朝历史上仅有的两位以嫡长子身分继承皇位的皇帝之一（另一位是其子咸丰帝）。");
            pEntries.Add("qing_zeng_guofan",
                "曾国藩（1811年11月26日—1872年3月12日），原名子城，字伯涵，号涤生，斋名求阙斋，湖南湘乡人（今双峰县荷叶镇）。生于清朝长沙府白杨坪（现属湖南省娄底市双峰县荷叶镇天子坪），谱名传豫，宗圣曾子七十世孙（系出曾氏南宗），晚清时期的重臣、名臣和功臣，湘军创始人和领袖，也是中国近代重要政治家、军事家、理学家、书法家、思想家、文学家、诗人、外交家、实业家、改革家、儒生，与胡林翼并称曾胡，与晚清另一重臣李鸿章有师徒关系。道光进士，曾任四川乡试正考官、翰林院侍讲学士、内阁学士等，擢礼部右侍郎、历署兵、吏部侍郎。");
            pEntries.Add("qing_zeng_guozhi",
                "曾国荃（1824年10月12日—1890年11月13日），一名子植，谱名传恒，字沅甫，号叔纯。湖南长沙府湘乡人，清朝军事家、官员、湘军将领。曾子七十世孙，曾国藩的九弟，湘军内部称之为曾老九，尊称为九帅。1864年湘军南京屠城时未加管制，背负恶名。");
            pEntries.Add("qing_zhang_tingyu",
                "张廷玉（1672年10月29日—1755年5月19日），字衡臣，号研斋，安徽桐城人，出身桐城张氏家族，清朝政治人物，康雍乾三朝重臣，《明史》总纂官，死后配享太庙。张廷玉在康熙39年（1700年）中进士。雍正朝，任礼部尚书、户部尚书、吏部尚书、保和殿大学士、军机大臣等，完善军机处制度。乾隆年间，加封太保，后因得罪乾隆帝，险些遭祸，后仍依雍正帝遗命配享太庙，是清朝唯一配享太庙的汉族大臣。");
            pEntries.Add("qing_zhang_xun",
                "张勳（1854年12月14日—1923年9月12日），原名张和，字少轩，号松寿老人，中国江西南昌府奉新县赤田村人。清朝官至江南提督，护理两江总督，民国时，为长江巡阅使、定武上将军。拥戴宣统帝复辟后获封忠勇亲王、直隶总督，是清朝以及中国历史上的末任亲王。1912年，宣统退位，民国建立，张勳在民国建立后仍忠于清室，刻意不剪发辫，故绰号辫帅，1914年袁世凯委任张勋为定武上将军，1915年张勋改所统「武卫前军」为「定武军」，此军为了表示忠于清朝，都不剪辫子，所以又称为辫子军、辫军。");
            pEntries.Add("qing_zhang_zhidong",
                "张之洞（1837年9月2日—1909年10月4日）。字孝达，一字香涛，号香岩，又号壶公、无竞居士，晚年自号抱冰，人称“张香帅”，直隶天津府南皮县（今河北省沧州市南皮县）人，晚清重臣。道光十七年八月初三生于贵州。咸丰二年（1852年）15岁中顺天乡试解元，同治二年（1863年）中进士第三名探花，据说是因为慈禧太后喜欢张之洞的文章，因此破例提拔，授翰林院编修。");
            pEntries.Add("qing_zuo_zongtang",
                "左宗棠（1812年11月10日—1885年9月5日），字季高，号湘上农人，署名今亮，谥文襄，湖南湘阴人，晚清重臣、湘军将领、政治家、文学家、军事家、外交家、实业家、改革家、诗人。一生亲历了讨伐太平天国、洋务运动、陕甘回变、新疆之役等重要中国历史事件。然在中法战争马尾海战后，以钦差大臣之名重整湘军督办福建、台湾海疆防务期间，壮志未酬病逝于福州，享寿73岁。宗棠少时屡试不第，功名止于举人，在醴陵渌江书院主讲二年，转而遍读群书，留意水利、农业，钻研舆地、兵法。");
            pEntries.Add("yuan_bayan",
                "伯颜，出身八邻部，元朝初年的军事家和政治人物。伯颜曾祖父失儿古额秃是成吉思汗帐下千户长，祖父阿剌黑曾任千户长（蒙古第26位开国功臣）兼断事官，从征西域有功，受封忽毡及附近地区为食邑。叔祖父是成吉思汗的名臣纳牙阿。父亲晓古台，曾随旭烈兀西征西亚，伯颜即在伊儿汗国生长，信奉景教。");
            pEntries.Add("yuan_chengzong",
                "元成宗铁穆耳，孛儿只斤氏，元朝皇帝及蒙古帝国大汗，于1294年5月至1307年2月在位，共约13年。元成宗系元世祖忽必烈孙，是世祖太子真金的第三子，他在其父、兄或早逝或推让后被立为储君，并于忽必烈逝世后即位。其去世后，上谥号钦明广孝皇帝，庙号成宗，蒙古语谥号完泽笃皇帝。");
            pEntries.Add("yuan_guo_shoujing",
                "郭守敬（1231年—1316年），字若思，邢台人，元朝天文学家、数学家和水利学家。元太宗三年（1231年），郭守敬生于邢州境内的邢台。王恂、郭守敬等同一位尼泊尔建筑师阿尼哥合作，在元大都兴建了一座新天文台，台上就安置着郭守敬所创制的天文仪器。它是当时世界上设备最完善的天文台之一。");
            pEntries.Add("yuan_hao_jing",
                "郝经（1223年—1275年8月9日），字伯常，陵川县鲁山（今属山西晋城）人。生于金末乱世，随父逃难到河南鲁山，又迁往顺天府（今河北保定），“家贫，昼则负薪米为养，暮则读书”。顺天府左副守帅机贾辅聘为家庭教师，又在蔡国万户张柔府作馆师，“二家藏书万卷，（郝）经博览无不通”。元好问称其“挺然一气，立于天地之间盖亦鲜矣”。");
            pEntries.Add("yuan_jiexisi",
                "揭傒斯（1274年—1344年），字曼硕，龙兴富州（今江西丰城）人，元代文学家、书法家、史学家。着有《揭文安公集》，《元诗选》编为《秋宜集》，另有今人李梦生整理《揭傒斯全集》。幼时家贫而读书刻苦，大德年间出游湘汉。延佑元年（1314年）由布衣授为翰林国史院编修，迁应奉翰林文字，前后三入翰林。");
            pEntries.Add("yuan_liu_bingzhong",
                "刘秉忠（1216年—1274年9月20日），原名侃，任官后，敕赐名秉忠，法名子聪，字仲晦，号藏春散人，祖籍金国瑞州（今辽宁省绥中县前卫镇），元朝政治家、儒学家，曾在世祖忽必烈时担任宰相，亦是为元朝建立政治体制、国号以及都城上都和大都的设计者。身故后谥文正，赠太傅、常山王。刘秉忠生于官宦之家，他祖籍瑞州（今江西省高安市），先祖曾仕于辽朝，金灭辽后，曾祖父改仕金朝，为金邢州节度副使，遂以邢州为籍。元太祖十五年（1220年），蒙古大将木华黎略定邢州，设都元帅府，刘秉忠的父亲刘润也在蒙古政权的地方机构中担任下级官吏。");
            pEntries.Add("yuan_mingzong",
                "元明宗和世㻋，是元朝皇帝，蒙古帝国大汗，1329年2月27日至1329年8月30日在位，在位185天。他去世后，谥号翼献景孝皇帝，庙号明宗，蒙古语称忽都笃皇帝。1340年10月25日，元顺帝为元明宗上汉语尊号顺天立道睿文智武大圣孝皇帝。");
            pEntries.Add("yuan_muqali",
                "木华黎，又作木合里、摩和赉等，蒙古札剌亦儿部人，元太祖成吉思汗麾下大将，蒙古第3位开国功臣（千户）。同博尔术、博尔忽、赤老温并称为成吉思汗的四杰。木华黎（；），又作木合里、摩和赉等，蒙古札剌亦儿部人，元太祖成吉思汗麾下大将，蒙古第3位开国功臣（千户）。木华黎出身蒙古札剌亦儿部落，世代居于斡难河。");
            pEntries.Add("yuan_ningzong",
                "元宁宗懿璘质班是元朝皇帝，蒙古帝国大汗。1332年10月23日－1332年12月14日在位，在位2个月。他去世后，谥号冲圣嗣孝皇帝，庙号宁宗。");
            pEntries.Add("yuan_renzong",
                "元仁宗爱育黎拔力八达，中国元朝皇帝及蒙古帝国大汗，于公元1311年4月至1320年3月在位，共计近9年。元仁宗早年助兄长海山即位，被海山立为皇太子（元朝的皇位继承人一律称皇太子），相约兄终弟及，叔侄相传。武宗逝世后，其即位，前后使用年号皇庆、延佑。去世后，谥号圣文钦孝皇帝，庙号仁宗，蒙古语称号普颜笃皇帝（蒙古语： ，鲍培转写：Buyan-tu qaγan，西里尔字母：Буянт хаан；又译巴颜图可汗。");
            pEntries.Add("yuan_shi_tianze",
                "史天泽出身真定汉军世侯家族，随父兄归附蒙古后参与灭金战争并长期镇守河北。他在忽必烈与阿里不哥争位时支持忽必烈，后来参与襄樊等对宋战事，官至中书右丞相。史天泽主张约束屠杀、采用汉地赋税和官僚制度，是元初汉军集团转入中央治理的重要人物。");
            pEntries.Add("yuan_shundi",
                "元顺帝妥懽（huān）贴睦尔，明朝谥号为顺帝，通称元顺帝，北元庙号为惠宗，故又称元惠宗，蒙古语称号乌哈噶图汗，又称至正帝、庚申帝、庚申君，中国元朝末代皇帝、蒙古帝国大汗。自公元1333年7月至1370年5月在位，共37年，作为全中国皇帝在位35年，而他离京北迁之日被认定为元朝灭亡之时，其残余势力被称为北元。此后他在漠南领导北元政权与明朝对峙，直至逝世。");
            pEntries.Add("yuan_taiding",
                "元泰定帝也孙铁木儿，是元朝皇帝，蒙古帝国大汗，在位5年，自1323年10月4日至1328年8月15日。他的父亲甘麻剌是元世祖太子真金的长子，并在1292年被封为晋王，出镇岭北；1302年也孙铁木儿在甘麻剌死后袭晋王位，直到1323年他被发动南坡之变刺杀元英宗的党羽推举接帝位。1328年他去世后不久，其叔父答剌麻八剌之孙元文宗以追究英宗之死为由起兵，击败了他的儿子天顺帝而掌握大权，使他没被授与谥号和庙号，因此历史上以其年号称之为泰定帝。");
            pEntries.Add("yuan_tianzhen",
                "元天顺帝阿剌吉八，是元朝皇帝，蒙古帝国大汗，泰定帝之子，亦是甘麻剌之孙、真金的曾孙。1328年10月4日至1328年11月14日在位，在位一个月十一天。元天顺帝阿剌吉八（；），是元朝皇帝，蒙古帝国大汗，泰定帝之子，亦是甘麻剌之孙、真金的曾孙。《元史》中两次出现元天顺帝的名字，《元史·泰定帝本纪》说“皇子阿速吉八为皇太子”，《元史·宗室世系表》作“皇太子阿里吉八”。");
            pEntries.Add("yuan_tuotuo",
                "脱脱，清代以后改译托克托，蔑儿乞氏，字大用，蒙古族蔑儿乞人。曾出任御史大夫和中书省右丞相。任内恢复科举制度、平反前任丞相伯颜造成的大量冤案，减轻剥削、放宽税政，乃元朝末年得民心的难得良官，后世称为「脱脱更化」。脱脱汉文化修养极高，亦是二十四史中《宋史》、《辽史》、《金史》的主编。");
            pEntries.Add("yuan_wang_baobao",
                "扩廓帖木儿（14世纪1330年代或之后—1375年9月17日），小字保保，汉名王保保。元朝大将察罕帖木儿外甥、养子。元末重要将领，亦是北元朝廷的支柱。封齐王，拜太尉知枢密院事、中书省平章政事、银青荣禄大夫。");
            pEntries.Add("yuan_wenzong",
                "元文宗图帖睦尔，是元朝皇帝，蒙古帝国大汗，两次在位，第一次在位时间为1328年10月16日—1329年4月3日；后复位，第二次在位时间为1329年9月8日—1332年9月2日，在位时间共4年，他是元武宗的次子。1330年5月25日，群臣为图帖睦尔上汉语尊号钦天统圣至德诚功大文孝皇帝。他去世后，谥号圣明元孝皇帝，庙号文宗，蒙古语称札牙笃皇帝。他早年被流放至海南，是中国历史上唯一曾到过海南的皇帝。");
            pEntries.Add("yuan_wu_cheng",
                "吴澄是元代经学家，长期讲学并整理儒家经典，学者称草庐先生。他尝试会通朱熹与陆九渊的学说，著有《吴文正集》等作品，并曾参与国子监教育与朝廷修书。其学术活动推动理学在元代传播，也培养了一批进入地方和中央官学的士人。");
            pEntries.Add("yuan_wuzong",
                "元武宗海山，孛儿只斤氏，是中国元朝皇帝及蒙古帝国大汗，于1307年6月至1311年1月在位近4年。1309年2月，群臣为其上汉文尊号统天继圣钦文英武大章孝皇帝。其逝世后，上谥号仁惠宣孝皇帝，庙号武宗，蒙古语称曲律皇帝。元武宗是其前任皇帝元成宗铁穆耳之侄，其父系元世祖忽必烈太子真金的次子答剌麻八剌。");
            pEntries.Add("yuan_xu_heng",
                "许衡（1209年5月8日—1281年3月23日），字仲平，又称鲁斋先生，怀州河内（今河南沁阳）人，元代理学家、教育家。许衡生于金卫绍王大安元年（宋宁宗嘉定二年、元太祖四年）九月丙寅。十六岁时，下决心求学，一心研究儒家经典。1232年，蒙古军攻破金国新郑，许衡被俘，但是后来获释。");
            pEntries.Add("yuan_yelu_chucai",
                "耶律楚材出身辽朝宗室后裔，金末在燕京任职，蒙古军占领当地后受到成吉思汗征召并长期随军西征。他以天文、医术和行政知识服务汗廷，窝阔台即位后主张设官征税、保护农耕人口，反对把华北变为牧场并以杀戮掠夺获取短期收益。他推动户籍、赋税和州县治理，官至中书令，为蒙古帝国由征服秩序转向治理汉地发挥重要作用。");
            pEntries.Add("yuan_yingzong",
                "元英宗硕德八剌，是元朝皇帝，蒙古帝国大汗，1320年4月19日—1323年9月4日在位，在位3年零5个月，是元仁宗之子。1321年11月28日，群臣为硕德八剌上汉语尊号继天体道敬文仁武大昭孝皇帝。去世后，谥号睿圣文孝皇帝，庙号英宗，蒙古语称号格坚皇帝。");
            pEntries.Add("yuan_yuji",
                "虞集（1272年—1348年），字伯生，祖籍仁寿（今属四川省），元代文学家。父虞汲曾任黄冈尉，宋亡后，徙居临川崇仁（今属江西省）。虞集自小聪敏，战乱流离之际，无书可读，其母杨氏以口授其《论语》、《孟子》、《左传》。元成宗大德元年（1297年）至大都，任大都路儒学教授，累迁秘书少监。");
            pEntries.Add("yuan_zhang_hongfan",
                "张弘范（1238年—1280年2月11日），字仲畴，元朝将领，易州定兴（辽朝时期属于南京道管辖，金朝时期属于中都路管辖，今属河北）人。曾参加过襄樊之战，后跟随元帅伯颜南下征宋，最后在厓山海战中带领元军灭亡南宋。元太宗六年正月初十日（1234年2月9日），金朝灭亡。元太宗十年（1238年），张弘范出生，他是元朝汝南王张柔第九子，有武艺，能赋诗，擅使马槊，身材魁梧，仪表堂堂。");
            pEntries.Add("yuan_zhao_mengfu",
                "赵孟頫（1254年10月22日—1322年7月30日），字子昂，号松雪道人，别号鸥波、水精宫道人，中年曾署名孟俯。两浙西路安吉州乌程（今浙江省湖州市吴兴区）人。元朝画家、诗人管道昇是赵孟頫之妻；画家王蒙是赵孟頫之外孙。赵孟頫为宋太祖后代，后选择与元朝合作，并受到皇帝宠爱，“荣际五朝，名满四海”，官至翰林学士承旨，是元代文人画、书法的领袖人物。此卡侧重赵孟頫进入元朝中枢后的仕宦经历，以及他以书法重建晋唐笔法传统的成就。");
            pEntries.Add("yuan_zhao_mengfu_blue",
                "赵孟頫（1254年10月22日—1322年7月30日），字子昂，号松雪道人，别号鸥波、水精宫道人，中年曾署名孟俯。两浙西路安吉州乌程（今浙江省湖州市吴兴区）人。元朝画家、诗人管道昇是赵孟頫之妻；画家王蒙是赵孟頫之外孙。赵孟頫为宋太祖后代，后选择与元朝合作，并受到皇帝宠爱，“荣际五朝，名满四海”，官至翰林学士承旨，是元代文人画、书法的领袖人物。此卡侧重赵孟頫在山水、人物与鞍马画中的复古探索，以及其艺术观念对元明画坛的影响。");
        }
    }
}
